const tabs=[['overview','Umumiy ko‘rinish','dashboard','Umumiy'],['documents','Hujjatlar','document','Hujjatlar'],['history','Tarix','clock','Tarix'],['archive','Doimiy hujjatlar','folder','Doimiy'],['info','Ma’lumotlar','company','Ma’lumot']];

const initials=(name:string)=>name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const Badge=StatusBadge;
/** Icon-only controls always carry both a tooltip and an accessible name. */
function IconAction({label,onClick,icon,disabled,className}:any){return <Tooltip><TooltipTrigger asChild><Button data-slot="button" variant="outline" size="icon" className={className} disabled={disabled} aria-label={label} onClick={onClick}><Icon name={icon}/></Button></TooltipTrigger><TooltipContent>{label}</TooltipContent></Tooltip>}
function Confirm({open,onOpenChange,title,description,confirm,onConfirm,icon}:any){return <AlertDialog open={open} onOpenChange={onOpenChange}><AlertDialogContent className="confirm-dialog"><AlertDialogHeader><AlertDialogTitle>{title}</AlertDialogTitle><AlertDialogDescription>{description}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Bekor qilish</AlertDialogCancel><AlertDialogAction onClick={onConfirm}>{icon&&<Icon name={icon}/>}{confirm}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>}
function Empty({title,text,action}:any){return <EmptyRoot className="empty"><EmptyHeader><EmptyMedia variant="icon"><Icon name="folder" size={27}/></EmptyMedia><EmptyTitle>{title}</EmptyTitle><EmptyDescription>{text}</EmptyDescription></EmptyHeader>{action&&<EmptyContent>{action}</EmptyContent>}</EmptyRoot>}
function Modal({open,onClose,title,description,children,wide=false}:any){const trigger=useRef<HTMLElement|null>(null);return <Dialog open={open} onOpenChange={v=>!v&&onClose()}><DialogContent onOpenAutoFocus={()=>{trigger.current=document.activeElement as HTMLElement}} onCloseAutoFocus={e=>{if(trigger.current?.isConnected){e.preventDefault();trigger.current.focus()}}} showCloseButton={false} className={`modal ${wide?'wide':''}`}><header><div><DialogTitle>{title}</DialogTitle><DialogDescription>{description}</DialogDescription></div><DialogClose asChild><Button variant="ghost" size="icon" aria-label="Yopish"><Icon name="close"/></Button></DialogClose></header>{children}</DialogContent></Dialog>}

function App({saved,session,logout}:any){
 const [initial]=useState(()=>migrateWorkspace(saved));
 const [companies,setCompanies]=useState<any[]>(initial.companies);
 const [docs,setDocs]=useState<any[]>(()=>initial.docs.map(recoverAnalysis));
 const [activity,setActivity]=useState<any[]>(initial.activity);
 const [profile,setProfile]=useState<any>(initial.profile);
 const [closed,setClosed]=useState<string[]>(initial.closed);
 const [route,setRoute]=useState(()=>appRoute(location.hash.slice(1),initial.companies));
 const [period,setPeriod]=useState(currentPeriod());
 const [query,setQuery]=useState('');
 const [filter,setFilter]=useState('all');
 const [modal,setModal]=useState<any>(null);
 const [error,setError]=useState('');
 const setToast=(message:string)=>notify.success(message);
 const [busy,setBusy]=useState(false);
 const [preview,setPreview]=useState('');
 const {openMobile:mobileMenu,setOpenMobile:setMobileMenu}=useSidebar();
 const [showExamples,setShowExamples]=useState(false);
 const [savedError,setSavedError]=useState('');
 const [saveStatus,setSaveStatus]=useState('saved');
 const [showSampleDocs,setShowSampleDocs]=useState(false);
 const [page,setPage]=useState(1);
 const pendingSave=useRef(false);
 const [aiAuto,setAiAuto]=useState(initial.aiAuto!==false);
 const [aiOpen,setAiOpen]=useState(false);
 useEffect(()=>{const update=()=>{setRoute(appRoute(location.hash.slice(1),companies));setQuery('');setFilter('all');setMobileMenu(false)};addEventListener('hashchange',update);return()=>removeEventListener('hashchange',update)},[companies]);
 const workspaceState={...initial,companies,docs,activity,closed,profile,aiAuto,workspace:profile?.workspace||initial.workspace};
 useEffect(()=>{let current=true;pendingSave.current=true;setSaveStatus('saving');const t=setTimeout(()=>{saveState(workspaceState).then(()=>{if(current){pendingSave.current=false;setSavedError('');setSaveStatus('saved')}}).catch(e=>{if(current){setSavedError(e.message||'Ma’lumotlar saqlanmadi.');setSaveStatus('error')}})},200);return()=>{current=false;clearTimeout(t)}},[companies,docs,activity,closed,profile,aiAuto]);
 useEffect(()=>{const warn=(e:BeforeUnloadEvent)=>{if(pendingSave.current||hasPendingWrites()){e.preventDefault();e.returnValue=''}};addEventListener('beforeunload',warn);return()=>removeEventListener('beforeunload',warn)},[]);
 useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview]);
 const parts=route.split('/');
 const company=parts[0]==='company'?companies.find(c=>c.id===parts[1]):null;
 const tab=tabs.some(t=>t[0]===parts[2])?parts[2]:'overview';
 useEffect(()=>setPage(1),[query,filter,period,company?.id,tab,showSampleDocs]);
 const mine=companies.filter(c=>!c.isDemo);
 const examples=companies.filter(c=>c.isDemo);
 const go=(r:string)=>{location.hash=r;setQuery('');setFilter('all');setMobileMenu(false)};
 const open=(value:any)=>{setMobileMenu(false);setModal(value);setError('');setPreview('')};
 const event=(title:string,c:any,detail:string,type='document')=>setActivity(a=>[{id:crypto.randomUUID(),title,companyId:c.id,detail:`${c.name} · ${detail}`,type,at:new Date().toISOString(),time:new Date().toLocaleTimeString('uz-UZ',{hour:'2-digit',minute:'2-digit'}),actor:profile?.fullName||'Buxgalter'},...a]);
 const ai=useAI({docs,setDocs,companies,onEvent:event,auto:aiAuto,enabled:!!profile,canAnalyze:()=>saveStatus==='saved'&&!pendingSave.current&&!hasPendingWrites()});
 const activeDoc=modal?.doc?(docs.find(d=>d.id===modal.doc.id)||modal.doc):null;
 const reopen=(id:string)=>setClosed(a=>a.filter(x=>x!==`${id}:${period}`));
 const current=company?companyRequirements(docs,company.id,period).filter(d=>showSampleDocs||!d.demo):[];
 const stats=summarize(current);
 const documentList=company?(tab==='archive'?docs.filter(d=>d.company===company.id&&d.scope==='permanent'&&(showSampleDocs||!d.demo)):current):[];
 const visible=documentList.filter(d=>(filter==='all'||(filter==='outstanding'?['missing','correction_requested'].includes(d.status):d.status===filter))&&`${d.title} ${d.fileName}`.toLowerCase().includes(query.toLowerCase()));
 function saveProfile(e:any){e.preventDefault();const f=new FormData(e.currentTarget);const value={fullName:String(f.get('fullName')).trim(),phone:String(f.get('phone')).trim(),email:String(f.get('email')||'').trim(),workspace:String(f.get('workspace')||'').trim()};const message=profileError(value);if(message){setError(message);return;}setProfile(value);setError('');setModal(null);go('dashboard');setToast('Profil saqlandi. Endi kompaniyalaringiz bilan ishlashingiz mumkin.');}
 function ProfileForm({editing=false}:any){const errorId=error?'profile-error':undefined;const bad=!!error;return <form onSubmit={saveProfile} className="profile-form" noValidate aria-describedby={errorId}><FieldGroup><Field data-invalid={bad||undefined}><FieldLabel htmlFor="profile-name">Ism va familiya</FieldLabel><Input id="profile-name" name="fullName" autoComplete="name" required maxLength={100} placeholder="Ism va familiyangiz" defaultValue={profile?.fullName||''} aria-invalid={bad||undefined} aria-describedby={errorId}/><FieldDescription>Hujjat qarorlarida va tarixda shu ism ko‘rinadi.</FieldDescription></Field><Field data-invalid={bad||undefined}><FieldLabel htmlFor="profile-phone">Telefon raqami</FieldLabel><Input id="profile-phone" name="phone" type="tel" inputMode="tel" autoComplete="tel" required maxLength={20} placeholder="+998 90 123 45 67" defaultValue={profile?.phone||''} aria-invalid={bad||undefined} aria-describedby={errorId}/></Field><Field><FieldLabel htmlFor="profile-email">Elektron pochta <span className="optional">Ixtiyoriy</span></FieldLabel><Input id="profile-email" name="email" type="email" inputMode="email" autoComplete="email" placeholder="siz@pochta.uz" defaultValue={profile?.email||''}/></Field><Field><FieldLabel htmlFor="profile-workspace">Buxgalteriya xizmatingiz nomi <span className="optional">Ixtiyoriy</span></FieldLabel><Input id="profile-workspace" name="workspace" maxLength={80} placeholder="Masalan, Hisob Servis" defaultValue={profile?.workspace||''}/><FieldDescription>Yon panelda ismingiz ostida ko‘rinadi.</FieldDescription></Field>{error&&<FieldError id="profile-error">{error}</FieldError>}<Button type="submit" className="full-width">{editing?'Saqlash':'Davom etish'}<Icon name="arrow" data-icon="inline-end"/></Button></FieldGroup><p className="form-footnote"><Icon name="shield" size={16}/>{session.storage==='server'?'Ma’lumotlar serverdagi ish joyingizda saqlanadi.':'Ma’lumotlar shu brauzerda saqlanadi.'}</p></form>}
 function addCompany(e:any){e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('name')).trim();const stir=String(f.get('stir')||'').trim();if(!name){setError('Kompaniya nomini kiriting.');return;}if(stir&&!/^\d{9}$/.test(stir)){setError(stirError);return;}if(stir&&companies.some(c=>c.stir===stir)){setError('Bu STIR bilan kompaniya avval qo‘shilgan.');return;}const c={id:crypto.randomUUID(),name,stir,legal:String(f.get('legal')),contact:String(f.get('contact')||'').trim(),phone:String(f.get('phone')||'').trim(),owner:profile.fullName,isDemo:false,createdAt:new Date().toISOString()};setCompanies(a=>[...a,c]);event('Kompaniya qo‘shildi',c,profile.fullName,'company');setModal(null);go(`company/${c.id}/overview`);setToast('Kompaniya qo‘shildi. Birinchi hujjatni yuklashingiz mumkin.');}
 const pageSize=15;const totalPages=Math.max(1,Math.ceil(visible.length/pageSize));const safePage=Math.min(page,totalPages);const pageDocs=visible.slice((safePage-1)*pageSize,safePage*pageSize);
 const aiPending=company?docs.filter(d=>d.company===company.id&&eligible(d)&&['queued','processing'].includes(d.ai?.status)).length:0;
 async function restoreWorkspace(value:any){await saveState(value);location.reload()}
 async function retrySave(){setSaveStatus('saving');try{await saveState(workspaceState);pendingSave.current=false;setSavedError('');setSaveStatus('saved')}catch(e:any){setSavedError(e.message);setSaveStatus('error')}}
 async function signOut(){try{await saveState(workspaceState);pendingSave.current=false;await logout()}catch(e:any){setSavedError(e.message)}}
 /** Opens a document from the home screen: the company's documents section first, then the review dialog. */
 function reviewDocument(d:any){if(!company||company.id!==d.company)go(`company/${d.company}/${d.scope==='permanent'?'archive':'documents'}`);void showDocument(d);}
 async function showDocument(d:any){if(d.status==='missing'){open({type:'upload',target:d});return;}open({type:'document',doc:d});if(!d.demo){try{const file=await getFile(d.fileKey||d.id,d.fileName);if(!file)throw Error();if(/\.(pdf|png|jpe?g)$/i.test(file.name))setPreview(URL.createObjectURL(file))}catch{setError('Asl fayl topilmadi. Qayta yuklab ko‘ring.')}}}
 async function upload(e:any,files:File[]){e.preventDefault();if(busy)return;const f=new FormData(e.currentTarget);if(!files.length){setError('Yuklash uchun fayl tanlang.');return;}if(files.length>(modal.target?1:20)){setError(modal.target?'Ushbu talab uchun bitta fayl tanlang.':'Bir martada 20 tagacha fayl yuklang.');return;}for(const file of files){const msg=validateFile(file);if(msg){setError(`${file.name}: ${msg}`);return;}}const owner=(modal.pick?companies.find(c=>c.id===String(f.get('company'))):null)||company;if(!owner){setError('Avval kompaniyani tanlang.');return;}setBusy(true);try{const items:any[]=[];for(const file of files){const old=modal.target;const fileKey=crypto.randomUUID();await putFile(fileKey,file);items.push({id:old?.id||crypto.randomUUID(),fileKey,versions:old?[...(old.versions||[]),{fileKey:old.fileKey||old.id,fileName:old.fileName,status:old.status}]:[],company:owner.id,title:old?.title||String(f.get('title')||'').trim()||file.name,fileName:file.name,status:'review_required',scope:old?.scope||String(f.get('scope')||'periodic'),period,date:new Date().toISOString().slice(0,10),size:file.size<1048576?Math.max(1,Math.round(file.size/1024))+' KB':(file.size/1048576).toFixed(1)+' MB',demo:false});}setDocs(all=>[...all.filter(d=>!items.some(x=>x.id===d.id)),...items]);setCompanies(all=>all.map(c=>c.id===owner.id?{...c,isDemo:false}:c));reopen(owner.id);event('Hujjat yuklandi',owner,files.map(x=>x.name).join(', '),'upload');setModal(null);if(!company)go(`company/${owner.id}/documents`);setToast(`${files.length} ta fayl saqlandi.${ai.connection.connected&&aiAuto?' Avtomatik tekshiruv fonda boshlanadi.':''}`);}catch{setError('Saqlash amalga oshmadi. Ulanishni va bo‘sh xotirani tekshiring.');}finally{setBusy(false)}}
 function decide(status:string,reason=''){try{const d=activeDoc;const owner=companies.find(c=>c.id===d.company)||company;const next={...transition(d,status,reason),reviewer:profile.fullName};setDocs(all=>all.map(x=>x.id===d.id?{...next,ai:x.ai}:x));event(status==='accepted'?'Hujjat qabul qilindi':'Tuzatish so‘raldi',owner,`${d.title}${reason?' · '+reason:''}`,status==='accepted'?'check':'request');setModal(null);setToast('Qaror kompaniya tarixida saqlandi.');}catch(e:any){setError(e.message)}}
 function requestDocument(e:any){e.preventDefault();const f=new FormData(e.currentTarget);const title=String(f.get('title')||'').trim();if(!title){setError('Hujjat nomini kiriting.');return;}setDocs(all=>[...all,{id:crypto.randomUUID(),company:company.id,title,fileName:'',period,status:'missing',scope:'periodic',date:new Date().toISOString().slice(0,10),size:'—',demo:false}]);reopen(company.id);setCompanies(all=>all.map(c=>c.id===company.id?{...c,isDemo:false}:c));event('Hujjat talabi yaratildi',company,title,'request');setModal(null);setToast('Talab saqlandi. Tashqi xabar yuborilmadi.');}
 async function download(d:any){try{const file=await getFile(d.fileKey||d.id,d.fileName);if(!file)throw Error();const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=d.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{setError('Asl fayl topilmadi.')}}
 function exportCSV(){const lines=[['Kompaniya','Hujjat','Davr','Holat'],...documentList.map(d=>[company.name,d.title,d.scope==='permanent'?'Doimiy':d.period,statuses[d.status]])];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${company.name}-${period}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setToast('Hujjatlar reyestri yuklab olindi.');}
 const shared=<>{savedError&&<Alert className="storage-error" role="alert">{savedError} <Button variant="ghost" onClick={retrySave}>Qayta saqlash</Button><Button variant="ghost" onClick={()=>open({type:'backup'})}>Zaxira olish</Button></Alert>}<Toaster theme="light" position="bottom-left" closeButton toastOptions={{duration:4500}}/></>;
 if(!profile)return <div className="onboarding"><header className="onboarding-header"><Brand href="#dashboard"/><Button variant="outline" onClick={()=>open({type:'backup'})}><Icon name="upload"/>Zaxiradan tiklash</Button></header><main className="onboarding-main"><aside className="onboarding-intro"><span className="section-kicker">Ishni boshlash</span><h1>Barcha kompaniyalaringiz.<br/>Bitta tartibli ish joyi.</h1><p>Hujjatlarni yig‘ing, tekshiring va har bir kompaniya bo‘yicha tarixni saqlang.</p><ol role="list" className="setup-steps"><li className="current"><span>1</span><div><strong>O‘zingizni tanishtiring</strong><p>Buxgalter ma’lumotlarini kiriting</p></div></li><li><span>2</span><div><strong>Kompaniya qo‘shing</strong><p>Xizmat ko‘rsatadigan tashkilotingiz</p></div></li><li><span>3</span><div><strong>Hujjatlar bilan ishlang</strong><p>Yuklang, tekshiring va tarixni kuzating</p></div></li></ol><div className="intro-footnote"><Icon name="folder"/>Hujjatlar har bir kompaniyada alohida saqlanadi.</div></aside><Card className="onboarding-form panel"><div className="step-label">1 / 3 · Buxgalter profili</div><h2>Avval siz bilan tanishamiz</h2><p className="form-description">Hujjatlardagi qarorlar va tarixda ismingiz ko‘rinadi. Keyingi qadam — birinchi kompaniyani qo‘shish.</p>{ProfileForm({})}</Card></main><Modal open={modal?.type==='backup'} onClose={()=>setModal(null)} title="Zaxira nusxalari" description="Ish joyingizni saqlash va ko‘chirish."><BackupPanel state={workspaceState} onRestore={restoreWorkspace}/></Modal><footer className="onboarding-footer">Hisobkor.uz · Buxgalterning kundalik ish joyi</footer>{shared}</div>;
 const sidebarContent=<>
  <SidebarHeader><Brand href="#dashboard"/><Button variant="ghost" size="icon" className="sidebar-mobile-close" aria-label="Menyuni yopish" onClick={()=>setMobileMenu(false)}><Icon name="close"/></Button></SidebarHeader>
  <SidebarContent>
  <SidebarMenu className="sidebar-nav home-nav" aria-label="Asosiy"><SidebarMenuItem><SidebarMenuButton className={company?'':'selected'} aria-current={company?undefined:'page'} onClick={()=>go('dashboard')}><Icon name="dashboard"/>Bosh sahifa</SidebarMenuButton></SidebarMenuItem></SidebarMenu>
  <div className="company-picker sidebar-nav"><Dropdown.DropdownMenu modal={false}><Dropdown.DropdownMenuTrigger asChild><Button variant="ghost" className="company-switcher" aria-label={company?`Kompaniyani almashtirish: ${company.name}`:'Kompaniya tanlash'}><Icon name="company"/><strong>{company?.name||'Kompaniya tanlash'}</strong><Icon name="down" size={16}/></Button></Dropdown.DropdownMenuTrigger><Dropdown.DropdownMenuContent className="company-dropdown" align="start" sideOffset={8} collisionPadding={12} onCloseAutoFocus={e=>{if(modal)e.preventDefault()}}><Dropdown.DropdownMenuLabel className="company-dropdown-label">Kompaniya tanlang</Dropdown.DropdownMenuLabel><div className="company-dropdown-list"><Dropdown.DropdownMenuRadioGroup value={company?.id||''} onValueChange={id=>go(`company/${id}/overview`)}>{(company?.isDemo?[...mine,company]:mine).map(c=><Dropdown.DropdownMenuRadioItem className="company-dropdown-item" key={c.id} value={c.id}><Icon name="company" size={18}/><span>{c.name}{c.isDemo&&<small>Namuna kompaniya</small>}</span></Dropdown.DropdownMenuRadioItem>)}</Dropdown.DropdownMenuRadioGroup>{!mine.length&&!company&&<p className="company-dropdown-empty">Hali kompaniya qo‘shilmagan</p>}</div><Dropdown.DropdownMenuSeparator className="company-dropdown-separator"/><Dropdown.DropdownMenuItem className="company-dropdown-item" onSelect={()=>go('dashboard')}><Icon name="dashboard"/>Bosh sahifa</Dropdown.DropdownMenuItem><Dropdown.DropdownMenuItem className="company-dropdown-item" onSelect={()=>open({type:'company'})}><Icon name="plus"/>Kompaniya qo‘shish</Dropdown.DropdownMenuItem></Dropdown.DropdownMenuContent></Dropdown.DropdownMenu></div>
  {company&&<div className="company-navigation"><SidebarMenu aria-label="Kompaniya bo‘limlari">{tabs.map(([id,label,icon])=><SidebarMenuItem key={id}><SidebarMenuButton className={tab===id?'selected':''} aria-current={tab===id?'page':undefined} onClick={()=>go(`company/${company.id}/${id}`)}><Icon name={icon}/>{label}</SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu></div>}
  </SidebarContent><SidebarFooter className="sidebar-bottom">
   <div className="sidebar-nav"><Button variant="ghost" onClick={()=>open({type:'backup'})}><Icon name="download"/>Zaxira nusxalari</Button><Button variant="ghost" onClick={()=>open({type:'help'})}><Icon name="help"/>Yordam</Button></div>
   <Dropdown.DropdownMenu modal={false}><Dropdown.DropdownMenuTrigger asChild><SidebarMenuButton size="lg" className="profile-button" aria-label="Hisob menyusi"><Avatar className="profile-avatar"><AvatarFallback>{initials(profile.fullName)}</AvatarFallback></Avatar><span><strong>{profile.fullName}</strong><small>{profile.workspace||'Buxgalter'}</small></span><Icon name="down" size={16}/></SidebarMenuButton></Dropdown.DropdownMenuTrigger><Dropdown.DropdownMenuContent className="account-dropdown company-dropdown" side="top" align="start" sideOffset={8} collisionPadding={12} onCloseAutoFocus={e=>{if(modal)e.preventDefault()}}><Dropdown.DropdownMenuGroup><Dropdown.DropdownMenuLabel className="company-dropdown-label">Mening hisobim</Dropdown.DropdownMenuLabel><Dropdown.DropdownMenuItem className="company-dropdown-item" onSelect={()=>open({type:'profile'})}><Icon name="settings"/>Profilni tahrirlash</Dropdown.DropdownMenuItem>{session.mode==='production'&&<><Dropdown.DropdownMenuSeparator className="company-dropdown-separator"/><Dropdown.DropdownMenuItem className="company-dropdown-item" onSelect={()=>open({type:'logout'})}><Icon name="logout"/>Chiqish</Dropdown.DropdownMenuItem></>}</Dropdown.DropdownMenuGroup></Dropdown.DropdownMenuContent></Dropdown.DropdownMenu>
  </SidebarFooter>
 </>;
 return <div className="app isolate antialiased"><a className="skip-link" href="#main-content" onClick={e=>{e.preventDefault();document.getElementById('main-content')?.focus()}}>Asosiy mazmunga o‘tish</a><Sidebar variant="inset" collapsible="offcanvas">{sidebarContent}</Sidebar><div className="workspace"><header className="topbar"><Tooltip><TooltipTrigger asChild><SidebarTrigger data-slot="sidebar-trigger" aria-label="Menyu"/></TooltipTrigger><TooltipContent>Menyu</TooltipContent></Tooltip><Breadcrumb className="breadcrumb" aria-label="Sahifa yo‘li"><BreadcrumbList><BreadcrumbItem>{company?<BreadcrumbLink href="#dashboard">Bosh sahifa</BreadcrumbLink>:<BreadcrumbPage>Bosh sahifa</BreadcrumbPage>}</BreadcrumbItem>{company&&<><BreadcrumbSeparator/><BreadcrumbItem><BreadcrumbLink href={`#company/${company.id}/overview`}>{company.name}</BreadcrumbLink></BreadcrumbItem></>}{company&&<><BreadcrumbSeparator className="breadcrumb-page"/><BreadcrumbItem className="breadcrumb-page"><BreadcrumbPage>{tabs.find(t=>t[0]===tab)?.[1]}</BreadcrumbPage></BreadcrumbItem></>}</BreadcrumbList></Breadcrumb><div className="topbar-actions"><span className="save-indicator" role="status"><Icon name={saveStatus==='error'?'alert':saveStatus==='saving'?'clock':'check'} size={15}/>{saveStatus==='error'?'Saqlanmadi':saveStatus==='saving'?'Saqlanmoqda…':'Saqlandi'}</span><Tooltip><TooltipTrigger asChild><Button data-slot="button" variant="ghost" size="icon" aria-label="Yordam" onClick={()=>open({type:'help'})}><Icon name="help"/></Button></TooltipTrigger><TooltipContent>Yordam: ish tartibi haqida qisqacha</TooltipContent></Tooltip></div></header><main className="main-content" id="main-content" tabIndex={-1}>

{!company?<><WorkspaceHome companies={companies} docs={docs} period={period} onPeriod={(value:string)=>setPeriod(value)} onOpenCompany={(id:string)=>go(`company/${id}/overview`)} onReview={reviewDocument} onUpload={()=>open({type:'upload',pick:true})} onAddCompany={()=>open({type:'company'})} banner={<>{mine.length===0&&<Card className="onboarding-progress panel"><CardHeader><CardTitle>2 / 3 · Kompaniya qo‘shish</CardTitle><CardDescription>Profilingiz tayyor. Endi birinchi mijoz tashkilotini qo‘shing, so‘ng uning hujjatlarini yuklaysiz.</CardDescription></CardHeader><CardContent><ol className="step-strip" role="list"><li><Icon name="check"/>Profil to‘ldirildi</li><li className="active"><span className="step-number">2</span>Kompaniya qo‘shish</li><li><span className="step-number">3</span>Hujjat yuklash va tekshirish</li></ol></CardContent></Card>}</>}/>{examples.length>0&&<section className="example-section"><Button variant="ghost" className="example-toggle" onClick={()=>setShowExamples(!showExamples)} aria-expanded={showExamples}><Icon name="folder"/>Avvalgi namuna kompaniyalar ({examples.length})<Icon name="down"/></Button>{showExamples&&<><p>Oldingi preview ma’lumotlari saqlangan. Bu kompaniyalar namuna uchun.</p><div className="company-grid">{examples.map(c=><CompanyCard key={c.id} c={c} docs={docs} onOpen={()=>go(`company/${c.id}/overview`)}/>)}</div></>}</section>}<p className="company-hint"><Icon name="shield"/><span>Har bir kompaniyaning hujjatlari, qarorlari va tarixi alohida saqlanadi.</span></p></>:<><PageHeader title={tabs.find(t=>t[0]===tab)?.[1]||'Kompaniya'} description={tab==='overview'?`${company.name} · ${company.legal||'MChJ'}${company.stir?' · STIR '+company.stir:''} · ${month(period)}`:tab==='archive'?'Doimiy hujjatlar — ustav, guvohnoma, shartnoma: oy almashganda ham shu yerda qoladi.':tab==='history'?'Kim, qachon va qaysi hujjat bo‘yicha qaror qabul qilgani.':tab==='info'?'Kompaniya rekvizitlari va mas’ul shaxslar.':`${month(period)} hujjatlari: qaysi biri tekshiruvni kutmoqda va qaysi biri qabul qilingan.`} actions={<>{['overview','documents'].includes(tab)&&<PeriodPicker value={period} min="2000-01" max="2100-12" onChange={(value:string)=>{setPeriod(value);setFilter('all')}}/>}{['overview','documents','archive'].includes(tab)&&<Button onClick={()=>open({type:'upload'})}><Icon name="upload"/>Hujjat yuklash</Button>}{tab==='info'&&<Button variant="outline" onClick={()=>open({type:'edit-company'})}><Icon name="settings"/>Tahrirlash</Button>}<Button variant="outline" className="ai-trigger" aria-label={`AI tahlil${aiPending?`: ${aiPending} ta hujjat tekshirilmoqda`:''}`} onClick={()=>setAiOpen(true)}><Icon name="spark"/>AI tahlil{aiPending>0&&<span className="ai-trigger-count" role="status">{aiPending}</span>}</Button></>}/><Tabs className="company-sections" value={tab} onValueChange={id=>go(`company/${company.id}/${id}`)}><TabsList className="company-tabs" aria-label="Kompaniya bo‘limlari">{tabs.map(([id,label,icon])=><TabsTrigger key={id} value={id}><Icon name={icon} size={17}/>{label}</TabsTrigger>)}</TabsList><TabsContent value={tab}>{tab==='overview'&&<CompanyOverview company={company} docs={docs} period={period} onNavigate={(section:string)=>go(`company/${company.id}/${section}`)} onOpen={showDocument} onUpload={()=>open({type:'upload'})}/>}
{['documents','archive'].includes(tab)&&<>{tab==='documents'&&current.length>0&&<ToggleGroup className="summary-strip" type="single" value={filter} onValueChange={value=>setFilter(value||'all')} aria-label="Hujjat holati bo‘yicha filtr">{[['all','Jami',current.length],...['review_required','correction_requested','missing','accepted'].map(key=>[key,statuses[key],current.filter(d=>d.status===key).length]).filter(x=>x[2]>0)].map(([key,label,count])=><ToggleGroupItem key={key} value={String(key)}>{label}<span className="filter-count">{count}</span></ToggleGroupItem>)}</ToggleGroup>}<Card className="documents-panel panel"><div className="document-toolbar"><SearchField placeholder="Hujjat nomini qidirish" aria-label="Hujjat qidirish" value={query} onChange={e=>setQuery(e.target.value)}/><div className="toolbar-actions"><NativeSelect name="status" value={filter} aria-label="Hujjat holati" onChange={e=>setFilter(e.target.value)}><NativeSelectOption value="all">Barcha holatlar</NativeSelectOption>{Object.entries(statuses).map(([key,value]:any)=><NativeSelectOption key={key} value={key}>{value}</NativeSelectOption>)}</NativeSelect>{tab==='documents'&&<Button variant="outline" onClick={()=>open({type:'request'})}><Icon name="plus"/>Hujjat so‘rash</Button>}<IconAction icon="download" disabled={!documentList.length} onClick={exportCSV} label="Hujjatlar reyestrini Excel (CSV) faylga yuklash"/></div></div>{visible.length?<div className="table-wrap"><Table><TableCaption className="sr-only">{company.name} hujjatlari</TableCaption><TableHeader><TableRow><TableHead scope="col">Hujjat</TableHead><TableHead scope="col">Sana</TableHead><TableHead scope="col">Holat</TableHead><TableHead scope="col">Avto tekshiruv</TableHead><TableHead scope="col"><span className="sr-only">Amal</span></TableHead></TableRow></TableHeader><TableBody>{pageDocs.map(d=><TableRow key={d.id}><TableCell><Button variant="ghost" className="document-name" onClick={()=>showDocument(d)}><span className="file-icon"><Icon name={d.status==='missing'?'request':'document'}/></span><span><strong>{documentName(d)}</strong><small>{d.demo?'Namuna hujjati':`${d.fileName?.split('.').pop()?.toUpperCase()||'Fayl'} · ${d.size}`}{d.reason?` · ${d.reason}`:''}</small></span></Button></TableCell><TableCell className="date-cell"><time dateTime={d.date||undefined}>{formatDate(d.date)||'—'}</time></TableCell><TableCell><Badge status={d.status}/></TableCell><TableCell className="ai-cell">{eligible(d)?<AIBadge doc={d}/>:<span className="muted">{d.demo?'Namuna':'Fayl kutilmoqda'}</span>}</TableCell><TableCell><Button variant="ghost" onClick={()=>showDocument(d)}>{d.status==='missing'?'Yuklash':d.status==='review_required'?'Tekshirish':'Ochish'}<Icon name="arrow" size={16}/></Button></TableCell></TableRow>)}</TableBody></Table></div>:<Empty title={documentList.length?'Hujjat topilmadi':tab==='archive'?'Doimiy hujjatlarni shu yerda saqlang':'Birinchi hujjatni yuklang'} text={documentList.length?'Qidiruvni yoki holat filtrini o‘zgartiring.':tab==='archive'?'Ustav, guvohnoma, shartnoma va rekvizitlarni shu yerga yuklang — ular oy almashganda ham kompaniyada qoladi.':`${month(period)} uchun PDF, rasm, Excel yoki CSV fayl yuklang. Yuklangandan keyin uni tekshirib, qabul qilasiz.`} action={!documentList.length&&<Button onClick={()=>open({type:'upload'})}><Icon name="upload"/>Hujjat yuklash</Button>}/>}<div className="table-footer"><span>{visible.length?`${(safePage-1)*pageSize+1}–${Math.min(safePage*pageSize,visible.length)} / ${visible.length} ta hujjat`:'0 ta hujjat'}</span><Pagination aria-label="Hujjat sahifalari"><PaginationContent><PaginationItem><Button variant="ghost" disabled={safePage<=1} onClick={()=>setPage(safePage-1)} aria-label="Oldingi sahifa"><Icon name="arrow" className="flip" size={16}/></Button></PaginationItem><PaginationItem><span>{safePage} / {totalPages}</span></PaginationItem><PaginationItem><Button variant="ghost" disabled={safePage>=totalPages} onClick={()=>setPage(safePage+1)} aria-label="Keyingi sahifa"><Icon name="arrow" size={16}/></Button></PaginationItem></PaginationContent></Pagination></div></Card>{docs.some(d=>d.company===company.id&&d.demo)&&<Label className="sample-switch"><Checkbox checked={showSampleDocs} onCheckedChange={v=>setShowSampleDocs(v===true)}/>Avvalgi namuna hujjatlarini ko‘rsatish</Label>}{tab==='documents'&&current.length>0&&<Card className="period-close panel"><CardHeader><CardTitle>Davrni yopish</CardTitle><CardDescription>{closed.includes(`${company.id}:${period}`)?`${month(period)} yopilgan. Yangi hujjat qo‘shilsa, davr o‘zi qayta ochiladi.`:stats.ready?`${month(period)} bo‘yicha barcha hujjatlar qabul qilingan. Davrni yopsangiz, oy yakunlangan deb belgilanadi.`:`${month(period)} hali yopilmaydi. Quyidagilar bajarilishi kerak:`}</CardDescription></CardHeader>{!stats.ready&&!closed.includes(`${company.id}:${period}`)&&<CardContent><ul className="blocker-list" role="list">{periodBlockers(current).map((b:any)=><li key={b.status}><StatusBadge status={b.status}/><span>{b.label}</span></li>)}</ul></CardContent>}<CardFooter><Button variant="outline" disabled={!stats.ready||closed.includes(`${company.id}:${period}`)} onClick={()=>open({type:'close'})}>{closed.includes(`${company.id}:${period}`)?'Davr yopilgan':'Davrni yopish'}</Button></CardFooter></Card>}</>}
{tab==='history'&&<section className="history-section"><Card className="panel">{companyHistory(activity,company).length?companyHistory(activity,company).map((a:any,i:number)=><div className="history-item" data-kind={a.type} key={a.id||i}><span className="history-symbol"><Icon name={a.type||'clock'}/></span><div className="history-copy"><div className="history-heading"><h3>{a.title}</h3><small>{a.actor||'Avvalgi preview'}</small></div><p>{a.detail?.replace(company.name+' · ','')}</p></div><time dateTime={a.at||undefined}>{formatDate(a.at)}<span>{a.time}</span></time></div>):<Empty title="Hali amallar yo‘q" text="Hujjat yuklaganingizda yoki qaror berganingizda, amal shu yerda sana va ismingiz bilan saqlanadi."/>}</Card></section>}
{tab==='info'&&<Card className="company-info panel"><CardContent><dl>{[['Kompaniya nomi',companyTitle(company)],['STIR',company.stir||'Kiritilmagan'],['Mas’ul buxgalter',company.isDemo?company.owner:profile.fullName],['Mijoz vakili',company.contact||'Kiritilmagan'],['Telefon raqami',company.phone||'Kiritilmagan'],['Asosiy valyuta','UZS — O‘zbekiston so‘mi']].map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl></CardContent></Card>}
</TabsContent></Tabs></>}
<footer className={`workspace-footer ${company?'has-ai-overlay':''}`}><span>Hisobkor.uz · Buxgalterning ish joyi</span><span>{session.storage==='server'?'Ma’lumotlar serverda saqlanadi':'Ma’lumotlar shu qurilmada saqlanadi'}</span></footer></main></div>
{company&&<BottomNav items={[['home','Bosh sahifa','dashboard','Bosh sahifa'],...tabs.filter(t=>t[0]!=='info')]} current={tab} onSelect={(id:string)=>go(id==='home'?'dashboard':`company/${company.id}/${id}`)}/>}
{company&&<AIOverlay key={company.id} company={company} docs={docs} ai={ai} open={aiOpen} onOpenChange={setAiOpen}/>}
<Modal open={modal?.type==='backup'} onClose={()=>setModal(null)} title="Zaxira nusxalari" description="Ish joyingizni saqlash va ko‘chirish."><BackupPanel state={workspaceState} onRestore={restoreWorkspace}/></Modal>

<Confirm open={modal?.type==='logout'} onOpenChange={(v:boolean)=>!v&&setModal(null)} title="Hisobdan chiqasizmi?" description="Ma’lumotlaringiz avval saqlanadi. Qaytish uchun hisobingizga qayta kirasiz." confirm="Chiqish" icon="logout" onConfirm={()=>{setModal(null);void signOut()}}/>
<Modal open={modal?.type==='profile'} onClose={()=>setModal(null)} title="Buxgalter profili" description="Qarorlar va tarixda ko‘rinadigan ma’lumotlaringiz.">{ProfileForm({editing:true})}</Modal>
<Modal open={modal?.type==='company'} onClose={()=>setModal(null)} title="Kompaniya qo‘shish" description="Avval nomini kiriting. Boshqa ma’lumotlar ixtiyoriy."><form onSubmit={addCompany}><CompanyFields error={error}/>{error&&error!==stirError&&<Alert role="alert" className="form-error">{error}</Alert>}<div className="modal-footer"><Button variant="outline" type="button" onClick={()=>setModal(null)}>Bekor qilish</Button><Button type="submit">Kompaniyani qo‘shish<Icon name="arrow"/></Button></div></form></Modal>
<Modal open={modal?.type==='edit-company'} onClose={()=>setModal(null)} title="Kompaniya ma’lumotlari" description={company?.name}><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const name=String(f.get('name')).trim();const stir=String(f.get('stir')||'').trim();if(!name){setError('Kompaniya nomini kiriting.');return;}if(stir&&!/^\d{9}$/.test(stir)){setError(stirError);return;}if(stir&&companies.some(c=>c.id!==company.id&&c.stir===stir)){setError('Bu STIR boshqa kompaniyada mavjud.');return;}const changes={name,stir,legal:String(f.get('legal')),contact:String(f.get('contact')||'').trim(),phone:String(f.get('phone')||'').trim()};setCompanies(all=>all.map(c=>c.id===company.id?{...c,...changes}:c));event('Kompaniya ma’lumotlari yangilandi',company,profile.fullName,'company');setModal(null);setToast('Ma’lumotlar saqlandi.');}}><CompanyFields company={company} error={error}/>{error&&error!==stirError&&<Alert role="alert" className="form-error">{error}</Alert>}<div className="modal-footer"><Button type="submit">Saqlash</Button></div></form></Modal>
<Modal open={modal?.type==='upload'} onClose={()=>!busy&&setModal(null)} title="Hujjat yuklash" description={modal?.pick?`${month(period)} · PDF, rasm, Excel yoki CSV fayl`:`${company?.name||''} · ${tab==='archive'?'Doimiy arxiv':month(period)}`}>
{modal?.type==='upload'&&<UploadForm onSubmit={upload} busy={busy} error={error} archive={tab==='archive'} target={modal.target} pick={!!modal.pick} companies={mine}/>}</Modal>
<Modal open={modal?.type==='request'} onClose={()=>setModal(null)} title="Hujjat so‘rash" description={`${company?.name||''} · ${month(period)}`}><form onSubmit={requestDocument} noValidate><FieldGroup><Field data-invalid={error?true:undefined}><FieldLabel htmlFor="request-title">Qanday hujjat kerak?</FieldLabel><Input id="request-title" required name="title" maxLength={120} placeholder="Masalan, sentabr oyi bank ko‘chirmasi" aria-invalid={error?true:undefined}/><FieldDescription>Talab ro‘yxatda “Kutilmoqda” holatida turadi va davr yopilishiga to‘sqinlik qiladi.</FieldDescription>{error&&<FieldError>{error}</FieldError>}</Field><Alert className="neutral-note"><Icon name="help"/>Talab kompaniya ro‘yxatiga qo‘shiladi. Hozircha mijozga avtomatik xabar yuborilmaydi.</Alert></FieldGroup><div className="modal-footer"><Button variant="outline" type="button" onClick={()=>setModal(null)}>Bekor qilish</Button><Button type="submit">Talab qo‘shish</Button></div></form></Modal>
<Modal open={modal?.type==='document'} onClose={()=>setModal(null)} title={activeDoc?documentName(activeDoc):'Hujjat'} description={company?.name} wide>{activeDoc&&<div className="document-detail"><section className="file-preview">{preview?(activeDoc.fileName.toLowerCase().endsWith('.pdf')?<iframe title="PDF hujjat" src={preview+'#navpanes=0&view=FitH'}/>:<img src={preview} alt={activeDoc.title}/>):<div className="file-placeholder"><Icon name="document" size={38}/><h3>{activeDoc.demo?'Namuna hujjati':'Fayl saqlangan'}</h3><p>{activeDoc.demo?'Avvalgi preview’dan qolgan namuna. Asl fayl biriktirilmagan.':'Excel yoki CSV faylini yuklab olib ochishingiz mumkin.'}</p><span>{activeDoc.fileName}</span></div>}</section><section className="document-details"><Badge status={activeDoc.status}/><div className="document-meta"><span className="file-icon"><Icon name="document"/></span><div><strong>{activeDoc.fileName}</strong><p>{formatDate(activeDoc.date)||'Sana ko‘rsatilmagan'} · {activeDoc.size}</p></div></div><AIReview doc={activeDoc} docs={docs} company={company} ai={ai} onRelated={showDocument}/>{!eligible(activeDoc)&&<Alert className="neutral-note"><Icon name="spark"/>Avtomatik tekshiruv bu hujjatni ko‘rmagan. Qarorni o‘zingiz berasiz.</Alert>}<dl><dt>Kompaniya</dt><dd>{company?.name}</dd><dt>Bo‘lim</dt><dd>{activeDoc.scope==='permanent'?'Doimiy hujjatlar':month(activeDoc.period)}</dd><dt>Fayl hajmi</dt><dd>{activeDoc.size}</dd>{activeDoc.reviewer&&<><dt>Qabul qilgan buxgalter</dt><dd>{activeDoc.reviewer}</dd></>}</dl>{activeDoc.reason&&<Alert className="neutral-note">{activeDoc.reason}</Alert>}{activeDoc.status==='review_required'&&<Card className="decision-card panel"><CardHeader><CardTitle>Qaroringiz</CardTitle><CardDescription>Hujjatni ko‘rib chiqing va bitta qarorni tanlang. Qaror kompaniya tarixida ismingiz bilan saqlanadi.</CardDescription></CardHeader><CardContent><Button className="full-width decision-accept" onClick={()=>decide('accepted')}><Icon name="check" data-icon="inline-start"/>Qabul qilish</Button><div className="decision-or"><Separator/><span>yoki</span><Separator/></div><form onSubmit={e=>{e.preventDefault();decide('correction_requested',String(new FormData(e.currentTarget).get('reason')||''))}}><FieldGroup><Field data-invalid={error?true:undefined}><FieldLabel htmlFor="decision-reason">Tuzatish sababi</FieldLabel><Textarea id="decision-reason" name="reason" rows={3} placeholder="Masalan, sentabr oyi o‘rniga avgust oyi hujjati yuklangan" aria-invalid={error?true:undefined} aria-describedby="decision-reason-hint"/>{error?<FieldError>{error}</FieldError>:<FieldDescription id="decision-reason-hint">Sabab majburiy: mijoz nimani tuzatishi kerakligini yozing.</FieldDescription>}</Field><Button type="submit" variant="outline" className="full-width"><Icon name="alert" data-icon="inline-start"/>Tuzatishga qaytarish</Button></FieldGroup></form></CardContent></Card>}{error&&activeDoc.status!=='review_required'&&<Alert className="form-error" role="alert">{error}</Alert>}{activeDoc.status==='correction_requested'&&<Button className="full-width" onClick={()=>open({type:'upload',target:activeDoc})}>Yangi nusxa yuklash</Button>}{!activeDoc.demo&&<Button variant="ghost" className="download-original full-width" onClick={()=>download(activeDoc)}><Icon name="download"/>Asl faylni yuklab olish</Button>}</section></div>}</Modal>
<Confirm open={modal?.type==='close'} onOpenChange={(v:boolean)=>!v&&setModal(null)} title={`${month(period)} davrini yopasizmi?`} description={`${company?.name||''} bo‘yicha barcha talablar qabul qilingan. Yopilgandan keyin yangi hujjat yoki talab qo‘shilsa, davr o‘zi qayta ochiladi.`} confirm="Davrni yopish" icon="check" onConfirm={()=>{if(!stats.ready){setToast('Hali bajarilmagan talablar bor.');return;}setClosed(a=>[...a,`${company.id}:${period}`]);event('Hisobot davri yopildi',company,month(period),'check');setModal(null);setToast('Davr yopildi.');}}/>
<Modal open={modal?.type==='help'} onClose={()=>setModal(null)} title="Hisobkor.uz bilan ishlash" description="Kundalik ish uchta qadamdan iborat."><div className="help-steps"><p><b>1. Bosh sahifadan boshlang.</b> U yerda tekshiruvingizni kutayotgan hujjatlar va har bir kompaniyaning shu oydagi holati ko‘rinadi.</p><p><b>2. Hujjatni oching va qaror bering.</b> “Tekshirish” tugmasi hujjat oynasini ochadi: uni qabul qilasiz yoki sabab bilan tuzatishga qaytarasiz.</p><p><b>3. Oyni yakunlang.</b> Barcha talablar qabul qilinganda “Davrni yopish” ishga tushadi. Barcha amallar “Tarix” bo‘limida saqlanadi.</p><Alert className="neutral-note">{session.storage==='server'?'Bu shaxsiy buxgalter kabineti. Ma’lumotlar serverda saqlanadi.':'Bu lokal ish joyi. Mavjud bo‘lsa, avtomatik tekshiruv fayllarga yordamchi xulosa beradi.'} Schyot-faktura va shartnoma rekvizitlari kompaniya ichida solishtiriladi. Didox va mijozga xabar yuborish ulanmagan. Brauzer ma’lumotlari o‘chirilsa, saqlangan fayllar ham yo‘qoladi.</Alert></div></Modal>
{shared}</div>;
}
function CompanyCard({c,docs,onOpen}:any){const all=docs.filter((d:any)=>d.company===c.id&&(c.isDemo||!d.demo));const n=all.filter((d:any)=>d.status==='review_required').length;const count=all.filter((d:any)=>d.status!=='missing').length;return <Card className="company-card"><CardContent className="company-row"><span className="company-mark"><Icon name="company" size={23}/></span><span className="company-card-info"><strong>{c.name}</strong><span>{c.legal||'MChJ'}{c.stir?` · STIR ${c.stir}`:''}</span></span><span className="company-card-count"><Icon name="document" size={16}/>{count} ta hujjat</span><span className={n?'review-count':'company-card-state'}>{n?`${n} ta tekshirish kerak`:'Ish joyini ochish'}</span><Button variant="outline" onClick={onOpen} aria-label={`${c.name} kompaniyasini ochish`}>Ochish<Icon name="arrow"/></Button></CardContent></Card>}

const stirError='STIR 9 ta raqamdan iborat bo‘lishi kerak.';
function CompanyFields({company,error}:any){const bad=error===stirError;return <FieldGroup><Field><FieldLabel htmlFor="company-name">Kompaniya nomi</FieldLabel><Input id="company-name" required name="name" maxLength={100} placeholder="Masalan, Atlas Savdo" defaultValue={company?.name||''}/><FieldDescription>Ro‘yxatlarda va hujjatlarda shu nom ko‘rinadi.</FieldDescription></Field><div className="form-grid"><Field><FieldLabel htmlFor="company-legal">Tashkiliy shakli</FieldLabel><NativeSelect id="company-legal" name="legal" defaultValue={company?.legal||'MChJ'}><NativeSelectOption>MChJ</NativeSelectOption><NativeSelectOption>YTT</NativeSelectOption><NativeSelectOption>AJ</NativeSelectOption><NativeSelectOption>Boshqa</NativeSelectOption></NativeSelect></Field><Field data-invalid={bad||undefined}><FieldLabel htmlFor="company-stir">STIR <span className="optional">Ixtiyoriy</span></FieldLabel><Input id="company-stir" name="stir" inputMode="numeric" autoComplete="off" maxLength={9} placeholder="9 ta raqam" defaultValue={company?.stir||''} aria-invalid={bad||undefined} aria-describedby={bad?'stir-error':'stir-hint'}/>{bad?<FieldError id="stir-error">{stirError}</FieldError>:<FieldDescription id="stir-hint">STIR kiritilsa, hujjatdagi rekvizitlar shu kompaniya bilan solishtiriladi.</FieldDescription>}</Field></div><Collapsible className="extra-fields" defaultOpen={!!company}><CollapsibleTrigger asChild><Button variant="ghost">Mijoz vakili va aloqa ma’lumotlari<Icon name="down" data-icon="inline-end"/></Button></CollapsibleTrigger><CollapsibleContent forceMount className="form-disclosure"><FieldGroup><Field><FieldLabel htmlFor="company-contact">Mijoz vakili <span className="optional">Ixtiyoriy</span></FieldLabel><Input id="company-contact" name="contact" autoComplete="name" maxLength={100} placeholder="Ism va familiya" defaultValue={company?.contact||''}/></Field><Field><FieldLabel htmlFor="company-phone">Telefon raqami <span className="optional">Ixtiyoriy</span></FieldLabel><Input id="company-phone" name="phone" type="tel" inputMode="tel" autoComplete="tel" maxLength={20} placeholder="+998" defaultValue={company?.phone||''}/></Field></FieldGroup></CollapsibleContent></Collapsible></FieldGroup>}
function UploadForm({onSubmit,busy,error,archive,target,companies,pick}:any){const [files,setFiles]=useState<File[]>([]);return <form onSubmit={e=>onSubmit(e,files)} noValidate><FieldGroup>{pick&&<Field><FieldLabel htmlFor="upload-company">Qaysi kompaniyaga?</FieldLabel><NativeSelect id="upload-company" name="company" defaultValue={companies[0]?.id}>{companies.map((c:any)=><NativeSelectOption key={c.id} value={c.id}>{c.name}</NativeSelectOption>)}</NativeSelect><FieldDescription>Fayl shu kompaniyaning hujjatlari orasida saqlanadi.</FieldDescription></Field>}<Field><FieldLabel className="drop-zone" htmlFor="upload-files" onDragOver={(e:any)=>e.preventDefault()} onDrop={(e:any)=>{e.preventDefault();setFiles(Array.from(e.dataTransfer.files))}}><span className="upload-circle"><Icon name="upload" size={24}/></span><strong>{files.length?`${files.length} ta fayl tanlandi`:'Fayl tanlang yoki shu yerga tashlang'}</strong><span>PDF, JPG, PNG, XLSX yoki CSV</span><small>Har bir fayl 25 MBgacha</small><Input id="upload-files" name="files" type="file" aria-label="Fayl tanlash" accept=".pdf,.jpg,.jpeg,.png,.xlsx,.csv" multiple={!target} onChange={e=>setFiles(Array.from(e.target.files||[]))}/></FieldLabel></Field>{target?<Alert className="neutral-note"><Icon name="request"/>Talab: {target.title}</Alert>:<><Field><FieldLabel htmlFor="upload-title">Hujjat nomi <span className="optional">Ixtiyoriy</span></FieldLabel><Input id="upload-title" name="title" maxLength={120} placeholder="Kiritmasangiz, fayl nomi saqlanadi"/></Field><Field><FieldLabel htmlFor="upload-scope">Saqlash joyi</FieldLabel><NativeSelect id="upload-scope" name="scope" defaultValue={archive?'permanent':'periodic'}><NativeSelectOption value="periodic">Oylik hujjatlar</NativeSelectOption><NativeSelectOption value="permanent">Doimiy hujjatlar</NativeSelectOption></NativeSelect><FieldDescription>Doimiy hujjatlar (ustav, shartnoma, guvohnoma) oy almashganda ham kompaniyada qoladi.</FieldDescription></Field></>}{files.length>0&&<ul role="list" className="file-list">{files.map((f,i)=><li key={i}><Icon name="document" size={16}/><span>{f.name}</span><small>{Math.max(1,Math.round(f.size/1024))} KB</small></li>)}</ul>}{error&&<FieldError>{error}</FieldError>}</FieldGroup><div className="modal-footer"><span className="upload-note">Yuklangan hujjat avtomatik qabul qilinmaydi — qarorni siz berasiz.</span><Button type="submit" disabled={busy}>{busy?<Spinner data-icon="inline-start"/>:<Icon name="upload" data-icon="inline-start"/>}{busy?'Saqlanmoqda…':'Yuklash'}</Button></div></form>}
createRoot(document.getElementById('root')!).render(<ErrorBoundary><Runtime>{({initial,session,logout}:any)=><TooltipProvider delayDuration={200}><SidebarProvider className="[--sidebar-width:15rem]"><App saved={initial} session={session} logout={logout}/></SidebarProvider></TooltipProvider>}</Runtime></ErrorBoundary>);
